<?php
require_once __DIR__ . '/_layout.php'; requirePermission('vehicles.manage');
if(requestMethod()==='POST'){requireCsrfPost();$action=$_POST['action']??'';try{$vehicle=dbFetchOne('SELECT * FROM vehicles WHERE id=:id',['id'=>(int)($_POST['vehicle_id']??0)]);if(!$vehicle)throw new InvalidArgumentException('Vehicle not found.');requireAgencyAccess($vehicle['agency_id']);if($action==='fine'){$amount=positiveMoney($_POST['amount']??'');if($amount===null)throw new InvalidArgumentException('Enter a valid fine amount.');$document=null;if(isset($_FILES['document'])&&($_FILES['document']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$document=storeValidatedDocument($_FILES['document'],'fines')['path'];dbExecute('INSERT INTO fines(vehicle_id,contract_id,customer_id,driver_name,occurred_at,fine_type,amount,administrative_fee,status,document_path,created_by)VALUES(:vehicle,:contract,:customer,:driver,:occurred,:type,:amount,:fee,\'pending\',:document,:user)',['vehicle'=>$vehicle['id'],'contract'=>($_POST['contract_id']??'')?:null,'customer'=>($_POST['customer_id']??'')?:null,'driver'=>trim((string)($_POST['driver_name']??'')),'occurred'=>$_POST['occurred_at'],'type'=>trim((string)($_POST['fine_type']??'')),'amount'=>$amount,'fee'=>positiveMoney($_POST['administrative_fee']??'0')??'0.00','document'=>$document,'user'=>currentUserId()]);auditLog('fine.created','fine',db()->lastInsertId(),null,['vehicle_id'=>$vehicle['id'],'amount'=>$amount],$vehicle['agency_id']);flash('success','Fine recorded.');}elseif($action==='accident'){$report=null;if(isset($_FILES['report'])&&($_FILES['report']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$report=storeValidatedDocument($_FILES['report'],'accidents')['path'];dbExecute('INSERT INTO accidents(vehicle_id,contract_id,customer_id,occurred_at,location,description,driver_name,accident_report_path,insurance_claim_number,insurance_excess,estimated_cost,customer_charge,replacement_vehicle_id,status,created_by)VALUES(:vehicle,:contract,:customer,:occurred,:location,:description,:driver,:report,:claim,:excess,:estimated,:charge,:replacement,\'reported\',:user)',['vehicle'=>$vehicle['id'],'contract'=>($_POST['contract_id']??'')?:null,'customer'=>($_POST['customer_id']??'')?:null,'occurred'=>$_POST['occurred_at'],'location'=>trim((string)($_POST['location']??'')),'description'=>trim((string)($_POST['description']??'')),'driver'=>trim((string)($_POST['driver_name']??'')),'report'=>$report,'claim'=>trim((string)($_POST['insurance_claim_number']??'')),'excess'=>positiveMoney($_POST['insurance_excess']??'0')??'0.00','estimated'=>positiveMoney($_POST['estimated_cost']??'0')??'0.00','charge'=>positiveMoney($_POST['customer_charge']??'0')??'0.00','replacement'=>($_POST['replacement_vehicle_id']??'')?:null,'user'=>currentUserId()]);$id=(int)db()->lastInsertId();dbExecute("UPDATE vehicles SET status='damaged',updated_by=:user WHERE id=:id",['user'=>currentUserId(),'id'=>$vehicle['id']]);auditLog('accident.created','accident',$id,null,['vehicle_id'=>$vehicle['id']],$vehicle['agency_id']);flash('success','Accident recorded and vehicle marked damaged.');}}catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Incident operation failed');flash('danger','The incident could not be recorded.');}safeRedirect('incidents.php');}
$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$vehicles=dbFetchAll("SELECT id,registration_number,brand,model FROM vehicles WHERE agency_id IN ($ph) AND archived_at IS NULL ORDER BY registration_number",$ids);$contracts=dbFetchAll("SELECT rc.id,rc.contract_number,r.customer_id,r.vehicle_id FROM rental_contracts rc JOIN reservations r ON r.id=rc.reservation_id WHERE r.agency_id IN ($ph) ORDER BY rc.created_at DESC LIMIT 200",$ids);$fines=dbFetchAll("SELECT f.*,v.registration_number,rc.contract_number FROM fines f JOIN vehicles v ON v.id=f.vehicle_id LEFT JOIN rental_contracts rc ON rc.id=f.contract_id WHERE v.agency_id IN ($ph) ORDER BY f.occurred_at DESC",$ids);$accidents=dbFetchAll("SELECT a.*,v.registration_number,rc.contract_number FROM accidents a JOIN vehicles v ON v.id=a.vehicle_id LEFT JOIN rental_contracts rc ON rc.id=a.contract_id WHERE v.agency_id IN ($ph) ORDER BY a.occurred_at DESC",$ids);
backofficeHeader('Incidents','incidents.php');?><?php pageHeader('Fines, accidents, and claims', 'Record fleet incidents and preserve their financial and contract context.', ['breadcrumbs'=>[['label'=>'Fleet'],['label'=>'Incidents']],'primary'=>['label'=>'Record incident','href'=>'#new-incident']]); ?><div class="grid"><section class="card" id="new-incident"><h2>Record fine</h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="fine"><label>Vehicle<select name="vehicle_id"><?php foreach($vehicles as $v):?><option value="<?=e($v['id'])?>"><?=e($v['registration_number'].' '.$v['brand'].' '.$v['model'])?></option><?php endforeach;?></select></label><label>Contract<select name="contract_id"><option value="">Unassigned</option><?php foreach($contracts as $c):?><option value="<?=e($c['id'])?>"><?=e($c['contract_number'])?></option><?php endforeach;?></select></label><label>Driver<input name="driver_name"></label><label>Date/time<input type="datetime-local" name="occurred_at" required></label><label>Fine type<input name="fine_type" required></label><label>Amount<input name="amount" required></label><label>Administrative fee<input name="administrative_fee" value="0.00"></label><label>Document<input type="file" name="document" accept="application/pdf,image/jpeg,image/png,image/webp"></label><button class="btn primary">Record fine</button></form></section><section class="card"><h2>Record accident</h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="accident"><label>Vehicle<select name="vehicle_id"><?php foreach($vehicles as $v):?><option value="<?=e($v['id'])?>"><?=e($v['registration_number'].' '.$v['brand'].' '.$v['model'])?></option><?php endforeach;?></select></label><label>Contract<select name="contract_id"><option value="">Unassigned</option><?php foreach($contracts as $c):?><option value="<?=e($c['id'])?>"><?=e($c['contract_number'])?></option><?php endforeach;?></select></label><label>Date/time<input type="datetime-local" name="occurred_at" required></label><label>Location<input name="location"></label><label>Driver<input name="driver_name"></label><label>Description<textarea name="description" required></textarea></label><label>Insurance claim<input name="insurance_claim_number"></label><label>Insurance excess<input name="insurance_excess" value="0.00"></label><label>Estimated cost<input name="estimated_cost" value="0.00"></label><label>Customer charge<input name="customer_charge" value="0.00"></label><label>Report<input type="file" name="report" accept="application/pdf,image/jpeg,image/png,image/webp"></label><button class="btn danger">Record accident</button></form></section></div><div class="grid" style="margin-top:1rem"><section class="card"><h2>Fines</h2><div class="table-wrap"><table><tr><th>Date</th><th>Vehicle</th><th>Contract</th><th>Type</th><th>Amount</th><th>Status</th></tr><?php foreach($fines as $f):?><tr><td><?=e($f['occurred_at'])?></td><td><?=e($f['registration_number'])?></td><td><?=e($f['contract_number'])?></td><td><?=e($f['fine_type'])?></td><td><?=money($f['amount']+$f['administrative_fee'])?></td><td><?=statusBadge($f['status'])?></td></tr><?php endforeach;?></table></div></section><section class="card"><h2>Accidents and claims</h2><div class="table-wrap"><table><tr><th>Date</th><th>Vehicle</th><th>Contract</th><th>Location</th><th>Estimated</th><th>Status</th></tr><?php foreach($accidents as $a):?><tr><td><?=e($a['occurred_at'])?></td><td><?=e($a['registration_number'])?></td><td><?=e($a['contract_number'])?></td><td><?=e($a['location'])?></td><td><?=money($a['estimated_cost'])?></td><td><?=statusBadge($a['status'])?></td></tr><?php endforeach;?></table></div></section></div><?php backofficeFooter();
